from typing import List

class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        suf = [0] * (n + 1)

        for i in range(n):
            pre[i + 1] = pre[i] | nums[i]

        for i in range(n - 1, -1, -1):
            suf[i] = suf[i + 1] | nums[i]

        ans = 0
        for i in range(n):
            boosted = nums[i] * (1 << k)
            total = pre[i] | boosted | suf[i + 1]
            if total > ans:
                ans = total

        return ans
